273	/**
274	 * 주문 배송 관련 비즈니스 로직을 처리하는 서비스
275	 */
276	@Slf4j
277	@Service
278	@RequiredArgsConstructor
279	public class OrderShipmentCommandService {
280	
281	    private final OrderShipmentRepository orderShipmentRepository;
282	    private final NotificationCommandService notificationCommandService;
283	    private final SaleBidQueryService saleBidQueryService;
284	    private final OrderBidQueryService orderBidQueryService;
285	    private final WarehouseStorageCommandService warehouseStorageCommandService;
286	    private final CjTrackingPlaywright cjTrackingPlaywright;
