288	    /**
289	     * 주문에 대한 배송 정보를 생성합니다.
290	     *
291	     * @param order 주문 엔티티
292	     * @param receiverName 수령인 이름
293	     * @param receiverPhone 수령인 전화번호
294	     * @param postalCode 우편번호
295	     * @param address 배송지 주소
296	     * @return 생성된 배송 정보
297	     */
298	    @Transactional
299	    public OrderShipment createOrderShipment(Order order, String receiverName, String receiverPhone,
300	                                             String postalCode, String address) {
301	        log.info("주문 배송 정보 생성 시작: orderId={}, receiverName={}",
302	                order.getId(), receiverName);
303	
304	        OrderShipment shipment = OrderShipment.builder()
305	                .order(order)
306	                .receiverName(receiverName)
307	                .receiverPhone(receiverPhone)
308	                .postalCode(postalCode)
309	                .address(address)
310	                .status(ShipmentStatus.PENDING) // 초기 상태 설정
311	                .build();
312	
313	        OrderShipment savedShipment = orderShipmentRepository.save(shipment);
314	        log.info("주문 배송 정보 생성 완료: shipmentId={}, orderId={}",
315	                savedShipment.getId(), order.getId());
316	
317	        return savedShipment;
318	    }
