320	    /**
321	     * 배송 상태를 업데이트합니다.
322	     *
323	     * @param shipment 업데이트할 배송 엔티티
324	     * @param newStatus 새로운 배송 상태
325	     */
326	    @Transactional
327	    public void updateShipmentStatus(OrderShipment shipment, ShipmentStatus newStatus) {
328	        log.info("배송 상태 업데이트: shipmentId={}, currentStatus={}, newStatus={}",
329	                shipment.getId(), shipment.getStatus(), newStatus);
330	
331	        try {
332	            shipment.updateStatus(newStatus);
333	            orderShipmentRepository.save(shipment);
334	
335	            log.info("배송 상태 업데이트 완료: shipmentId={}, status={}",
336	                    shipment.getId(), newStatus);
337	        } catch (IllegalStateException e) {
338	            log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
339	                    shipment.getId(), e.getMessage(), e);
340	
341	            throw new ShipmentException(
342	                    ShipmentErrorCode.INVALID_SHIPMENT_STATUS_TRANSITION,
343	                    "유효하지 않은 배송 상태 전환입니다: " + e.getMessage(),
344	                    e
345	            );
346	        }
347	    }
