349	    /**
350	     * 주문 완료에 따라 판매 상태를 'SOLD'로 변경합니다.
351	     *
352	     * @param orderId 주문 ID
353	     */
354	    @Transactional
355	    public void updateSaleStatusToSold(Long orderId) {
356	        log.info("판매 상태를 'SOLD'로 변경 시작: orderId={}", orderId);
357	
358	        // SaleBid 조회
359	        SaleBid saleBid = saleBidQueryService.findByOrderId(orderId);
360	        if (saleBid != null) {
361	            Sale sale = saleBid.getSale();
362	            if (sale != null && sale.getStatus().canTransitionTo(SaleStatus.SOLD)) {
363	                log.info("Sale 상태 'SOLD'로 변경: saleId={}, sellerId={}",
364	                        sale.getId(), sale.getSeller().getId());
365	
366	                sale.updateStatus(SaleStatus.SOLD); // 더티 체크에 의해 자동으로 업데이트됨
367	
368	                // 창고 상태 업데이트
369	                if (sale.isWarehouseStorage()) {
370	                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
371	                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
372	                }
373	
374	                // 판매자에게 알림 생성
375	                User seller = sale.getSeller();
376	                notificationCommandService.createNotification(
377	                        seller.getId(),
378	                        NotificationCategory.SHOPPING,
379	                        NotificationType.BID,
380	                        "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
381	                );
382	
383	                log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
384	                        seller.getId(), sale.getId());
385	            } else {
386	                log.debug("Sale 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
387	            }
388	        } else {
389	            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
390	        }
391	
392	        // OrderBid 조회
393	        try {
394	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
395	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
396	
397	            if (orderBid != null) {
398	                Sale sale = orderBid.getSale();
399	                if (sale != null && sale.getStatus().canTransitionTo(SaleStatus.SOLD)) {
400	                    log.info("OrderBid 기반 Sale 상태 'SOLD'로 변경: orderBidId={}, saleId={}",
401	                            orderBid.getId(), sale.getId());
402	
403	                    sale.updateStatus(SaleStatus.SOLD); // 더티 체크에 의해 자동으로 업데이트됨
404	
405	                    // 판매자에게 알림 생성
406	                    User seller = sale.getSeller();
407	                    notificationCommandService.createNotification(
408	                            seller.getId(),
409	                            NotificationCategory.SHOPPING,
410	                            NotificationType.BID,
411	                            "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
412	                    );
413	
414	                    log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
415	                            seller.getId(), sale.getId());
416	                } else {
417	                    log.debug("Sale 상태 변경 불가 또는 Sale이 null: orderBidId={}", orderBid.getId());
418	                }
419	            }
420	        } catch (IllegalArgumentException e) {
421	            log.warn("OrderBid 조회 실패: orderId={}, error={}", orderId, e.getMessage());
422	            // OrderBid가 없는 경우 예외로 중단하지 않고 진행
423	        }
424	
425	        log.info("판매 상태 'SOLD' 변경 작업 완료: orderId={}", orderId);
426	    }
