428	    /**
429	     * 주문을 완료 상태로 변경하고 관련된 후속 작업을 처리합니다.
430	     *
431	     * @param orderId 완료할 주문 ID
432	     */
433	    @Transactional
434	    public void completeOrder(Long orderId) {
435	        log.info("주문 완료 처리 시작: orderId={}", orderId);
436	
437	        try {
438	            // OrderBid 조회
439	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
440	                    .orElseThrow(() -> new IllegalArgumentException("OrderBid가 존재하지 않습니다. orderId=" + orderId));
441	
442	            Order order = orderBid.getOrder();
443	            log.debug("주문 정보 조회: orderId={}, userId={}, currentStatus={}",
444	                    order.getId(), order.getUser().getId(), order.getStatus());
445	
446	            // 주문 상태를 COMPLETED로 변경
447	            order.updateStatus(OrderStatus.COMPLETED);
448	            log.info("주문 상태 COMPLETED로 변경: orderId={}", orderId);
449	
450	            // 판매 상태 변경 로직
451	            updateSaleStatusToSold(orderId);
452	
453	            // 주문 완료 알림
454	            User buyer = order.getUser();
455	            notificationCommandService.createNotification(
456	                    buyer.getId(),
457	                    NotificationCategory.SHOPPING,
458	                    NotificationType.BID,
459	                    "[completeOrder] 주문이 완료 처리되었습니다. 주문 ID: " + order.getId()
460	            );
461	
462	            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());
