257	public enum ShipmentStatus {
258	    PENDING {
259	        @Override
260	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
261	            return nextStatus == SHIPPED || nextStatus == CANCELED;
262	        }
263	    },
264	    SHIPPED {
265	        @Override
266	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
267	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
268	        }
269	    },
270	    IN_TRANSIT {
271	        @Override
272	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
273	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
274	                    || nextStatus == DELIVERED;
275	        }
276	    },
277	    OUT_FOR_DELIVERY {
278	        @Override
279	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
280	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
281	        }
282	    },
283	    DELIVERED {
284	        @Override
285	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
286	            return false; // 배송 완료 이후로는 상태 전환 없음
287	        }
288	    },
289	    RETURNED {
290	        @Override
291	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
292	            return nextStatus == CANCELED;
293	        }
294	    },
295	    CANCELED {
296	        @Override
297	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
298	            return false; // 취소 이후 상태 전환 없음
299	        }
300	    },
301	    DELAYED {
302	        @Override
303	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
304	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
305	        }
306	    },
307	    FAILED_DELIVERY {
308	        @Override
309	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
310	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
311	        }
312	    };
313	
314	    public abstract boolean canTransitionTo(ShipmentStatus nextStatus);
315	}

